1	// TODO(cloudflare): workspace-operation-log-store.ts implements a
2	// local-file-backed workspace operation log store using node:fs
3	// (createReadStream, writeFile, appendFile, stat, mkdir). Operation logs are
4	// written to ~/.paperclip/data/workspace-operation-logs/ during workspace
5	// operations and read back via byte-range streaming. For Workers compatibility
6	// this must be replaced with an R2-backed implementation (multipart upload or
7	// Durable Object buffering), analogous to the run-log-store migration. The
8	// WorkspaceOperationLogStore interface is already abstract so only this
9	// implementation module and getWorkspaceOperationLogStore() need to change.
10	import { createReadStream, promises as fs } from "node:fs";
11	import path from "node:path";
12	import { createHash } from "node:crypto";
13	import { notFound } from "../errors.js";
14	import { resolvePaperclipInstanceRoot } from "../home-paths.js";
15	
16	export type WorkspaceOperationLogStoreType = "local_file";
17	
18	export interface WorkspaceOperationLogHandle {
19	  store: WorkspaceOperationLogStoreType;
20	  logRef: string;
21	}
22	
23	export interface WorkspaceOperationLogReadOptions {
24	  offset?: number;
25	  limitBytes?: number;
26	}
27	
28	export interface WorkspaceOperationLogReadResult {
29	  content: string;
30	  nextOffset?: number;
31	}
32	
33	export interface WorkspaceOperationLogFinalizeSummary {
34	  bytes: number;
35	  sha256?: string;
36	  compressed: boolean;
37	}
38	
39	export interface WorkspaceOperationLogStore {
40	  begin(input: { companyId: string; operationId: string }): Promise<WorkspaceOperationLogHandle>;
41	  append(
42	    handle: WorkspaceOperationLogHandle,
43	    event: { stream: "stdout" | "stderr" | "system"; chunk: string; ts: string },
44	  ): Promise<void>;
45	  finalize(handle: WorkspaceOperationLogHandle): Promise<WorkspaceOperationLogFinalizeSummary>;
46	  read(handle: WorkspaceOperationLogHandle, opts?: WorkspaceOperationLogReadOptions): Promise<WorkspaceOperationLogReadResult>;
47	}
48	
49	function safeSegments(...segments: string[]) {
50	  return segments.map((segment) => segment.replace(/[^a-zA-Z0-9._-]/g, "_"));
51	}
52	
53	function resolveWithin(basePath: string, relativePath: string) {
54	  const resolved = path.resolve(basePath, relativePath);
55	  const base = path.resolve(basePath) + path.sep;
56	  if (!resolved.startsWith(base) && resolved !== path.resolve(basePath)) {
57	    throw new Error("Invalid log path");
58	  }
59	  return resolved;
60	}
61	
62	function createLocalFileWorkspaceOperationLogStore(basePath: string): WorkspaceOperationLogStore {
63	  async function ensureDir(relativeDir: string) {
64	    const dir = resolveWithin(basePath, relativeDir);
65	    await fs.mkdir(dir, { recursive: true });
66	  }
67	
68	  async function readFileRange(filePath: string, offset: number, limitBytes: number): Promise<WorkspaceOperationLogReadResult> {
69	    const stat = await fs.stat(filePath).catch(() => null);
70	    if (!stat) throw notFound("Workspace operation log not found");
71	
72	    const start = Math.max(0, Math.min(offset, stat.size));
73	    const end = Math.max(start, Math.min(start + limitBytes - 1, stat.size - 1));
74	
75	    if (start > end) {
76	      return { content: "", nextOffset: start };
77	    }
78	
79	    const chunks: Buffer[] = [];
80	    await new Promise<void>((resolve, reject) => {
81	      const stream = createReadStream(filePath, { start, end });
82	      stream.on("data", (chunk) => {
83	        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
84	      });
85	      stream.on("error", reject);
86	      stream.on("end", () => resolve());
87	    });
88	
89	    const content = Buffer.concat(chunks).toString("utf8");
90	    const nextOffset = end + 1 < stat.size ? end + 1 : undefined;
91	    return { content, nextOffset };
92	  }
93	
94	  async function sha256File(filePath: string): Promise<string> {
95	    return new Promise<string>((resolve, reject) => {
96	      const hash = createHash("sha256");
97	      const stream = createReadStream(filePath);
98	      stream.on("data", (chunk) => hash.update(chunk));
99	      stream.on("error", reject);
100	      stream.on("end", () => resolve(hash.digest("hex")));
101	    });
102	  }
103	
104	  return {
105	    async begin(input) {
106	      const [companyId] = safeSegments(input.companyId);
107	      const operationId = safeSegments(input.operationId)[0]!;
108	      const relDir = companyId;
109	      const relPath = path.join(relDir, `${operationId}.ndjson`);
110	      await ensureDir(relDir);
111	
112	      const absPath = resolveWithin(basePath, relPath);
113	      await fs.writeFile(absPath, "", "utf8");
114	
115	      return { store: "local_file", logRef: relPath };
116	    },
117	
118	    async append(handle, event) {
119	      if (handle.store !== "local_file") return;
120	      const absPath = resolveWithin(basePath, handle.logRef);
121	      const line = JSON.stringify({
122	        ts: event.ts,
123	        stream: event.stream,
124	        chunk: event.chunk,
125	      });
126	      await fs.appendFile(absPath, `${line}\n`, "utf8");
127	    },
128	
129	    async finalize(handle) {
130	      if (handle.store !== "local_file") {
131	        return { bytes: 0, compressed: false };
132	      }
133	      const absPath = resolveWithin(basePath, handle.logRef);
134	      const stat = await fs.stat(absPath).catch(() => null);
135	      if (!stat) throw notFound("Workspace operation log not found");
136	
137	      const hash = await sha256File(absPath);
138	      return {
139	        bytes: stat.size,
140	        sha256: hash,
141	        compressed: false,
142	      };
143	    },
144	
145	    async read(handle, opts) {
146	      if (handle.store !== "local_file") {
147	        throw notFound("Workspace operation log not found");
148	      }
149	      const absPath = resolveWithin(basePath, handle.logRef);
150	      const offset = opts?.offset ?? 0;
151	      const limitBytes = opts?.limitBytes ?? 256_000;
152	      return readFileRange(absPath, offset, limitBytes);
153	    },
154	  };
155	}
156	
157	let cachedStore: WorkspaceOperationLogStore | null = null;
158	
159	export function getWorkspaceOperationLogStore() {
160	  if (cachedStore) return cachedStore;
161	  const basePath = process.env.WORKSPACE_OPERATION_LOG_BASE_PATH
162	    ?? path.resolve(resolvePaperclipInstanceRoot(), "data", "workspace-operation-logs");
163	  cachedStore = createLocalFileWorkspaceOperationLogStore(basePath);
164	  return cachedStore;
165	}
